"""
food_data.py — Indian + global food database with nutrient profiles.

All nutrient values are PER 100 g of edible portion (per 100 ml for liquids —
items with "serving_unit":"ml"). `serving_g` is the typical single portion, used
only as the default quantity in the picker.

Each item: { id, name, category, emoji, serving_g, [serving_unit],
             calories(kcal), protein/carbs/fat/fiber/sugar (g), sodium (mg),
             vit_a (ug RAE), vit_c (mg), vit_d (ug), vit_b12 (ug), vit_b6 (mg),
             folate (ug), iron/calcium/magnesium/zinc (mg),
             [piece] {unit,g}: for discrete foods logged by count (e.g.
                     one almond = 1.2 g) — the picker offers a count stepper,
             source }   # `source` is provenance only — never shown in the UI.

Values verified against USDA FoodData Central (global/whole foods), IFCT 2017
(Indian & South-Asian dishes), and manufacturer labels (branded/supplements).
"""
